typedef struct ArcNode {
    int adjvex;
    struct ArcNode *next;
} ArcNode;
ArcNode *adj[20];   /* 各顶点边表的头指针 */
void AddArc(int u, int v)    /* 头插法 */
{
    ArcNode *p;
    p = (ArcNode *)malloc(sizeof(ArcNode));
    p->adjvex = v;
    p->next = adj[u];
    adj[u] = p;
}
int main(void)
{
    int n, e, u, v, Q[20], front = 0, rear = 0;
    int visited[20] = {0};
    ArcNode *p;
    scanf("%d%d", &n, &e);
    while (e-- > 0) {
        scanf("%d%d", &u, &v);
        AddArc(u, v);
        AddArc(v, u);
    }
    visited[0] = 1;
    Q[rear++] = 0;
    while (front != rear) {
        u = Q[front++];
        printf("%d ", u);
        for (p = adj[u]; p != NULL; p = p->next)
            if (!visited[p->adjvex]) {
                visited[p->adjvex] = 1;
                Q[rear++] = p->adjvex;
            }
    }
    printf("\n");
    return 0;
}

