#include <stdio.h>
#define MAXV 20
#define INF 32767
int G[MAXV][MAXV];
int main(void)
{
    int n, e, u, v, w, i, k = 0, min, sum = 0;
    int lowcost[MAXV], closest[MAXV];
    scanf("%d%d", &n, &e);
    for (u = 0; u < n; u++)
        for (v = 0; v < n; v++)
            G[u][v] = INF;
    while (e-- > 0) {
        scanf("%d%d%d", &u, &v, &w);
        G[u][v] = G[v][u] = w;
    }
    for (v = 0; v < n; v++) {
        lowcost[v] = G[0][v];
        closest[v] = 0;
    }
    lowcost[0] = 0;
    for (i = 1; i < n; i++) {
        min = INF;
        for (v = 0; v < n; v++)
            if (lowcost[v] && lowcost[v] < min) {
                min = lowcost[v];
                k = v;
            }
        printf("%d %d %d\n", closest[k], k, min);
        sum += min;
        lowcost[k] = 0;
        for (v = 0; v < n; v++)
            if (G[k][v] < lowcost[v]) {
                lowcost[v] = G[k][v];
                closest[v] = k;
            }
    }
    printf("%d\n", sum);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
typedef struct {
    int u, v, w;
} Edge;
int parent[20];
int cmp(const void *a, const void *b)
{
    return ((Edge *)a)->w - ((Edge *)b)->w;
}
int Find(int x)
{
    while (parent[x] != -1)
        x = parent[x];
    return x;
}
int main(void)
{
    Edge E[100], *p;
    int n, e, i, r1, r2, cnt = 0, sum = 0;
    scanf("%d%d", &n, &e);
    for (p = E; p < E + e; p++)
        scanf("%d%d%d", &p->u, &p->v, &p->w);
    for (i = 0; i < n; i++)
        parent[i] = -1;
    qsort(E, e, sizeof(Edge), cmp);
    for (i = 0; i < e && cnt < n - 1; i++) {
        p = &E[i];
        r1 = Find(p->u);
        r2 = Find(p->v);
        if (r1 == r2)
            continue;
        parent[r1] = r2;
        printf("%d %d %d\n", p->u, p->v, p->w);
        sum += p->w;
        cnt++;
    }
    printf("%d\n", sum);
    return 0;
}

#include <stdio.h>
#define MAXV 20
#define INF 32767
/* s[v] 为 1 表示 v 的最短路径已经求出 */
int G[MAXV][MAXV], s[MAXV];

int main(void)
{
    int n, e, u = 0, v, w, i, min, dist[MAXV];
    scanf("%d%d", &n, &e);
    for (u = 0; u < n; u++)
        for (v = 0; v < n; v++)
            G[u][v] = INF;
    while (e-- > 0) {
        scanf("%d%d%d", &u, &v, &w);
        G[u][v] = w;
    }
    for (v = 0; v < n; v++)
        dist[v] = G[0][v];
    dist[0] = 0;
    s[0] = 1;
    for (i = 1; i < n; i++) {
        min = INF;
        for (v = 0; v < n; v++)
            if (!s[v] && dist[v] < min) {
                min = dist[v];
                u = v;
            }
        s[u] = 1;
        printf("%d %d\n", u, min);
        for (v = 0; v < n; v++)
            if (!s[v] && min + G[u][v] < dist[v])
                dist[v] = min + G[u][v];
    }
    return 0;
}

#include <stdio.h>
#define MAXV 20
int G[MAXV][MAXV], indegree[MAXV];

int main(void)
{
    int n, e, u, v, st[MAXV], top = -1, cnt = 0;
    scanf("%d%d", &n, &e);
    while (e-- > 0) {
        scanf("%d%d", &u, &v);
        G[u][v] = 1;
        indegree[v]++;
    }
    for (v = 0; v < n; v++)
        if (indegree[v] == 0)
            st[++top] = v;
    while (top != -1) {
        u = st[top--];
        printf("%d ", u);
        cnt++;
        for (v = 0; v < n; v++)
            if (G[u][v] && --indegree[v] == 0)
                st[++top] = v;
    }
    if (cnt < n)
        printf("cycle");
    printf("\n");
    return 0;
}
